  1→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
  2→import type {
  3→	ProviderName,
  4→	RemediationPromptsResponse,
  5→	TargetAgent,
  6→} from "../hooks/useEvaluationApi";
  7→import { useEvaluationApi } from "../hooks/useEvaluationApi";
  8→import {
  9→	type ProviderStatus,
 10→	useProviderDetection,
 11→} from "../hooks/useProviderDetection";
 12→import { useSSE } from "../hooks/useSSE";
 13→import type { EvaluationOutput, Issue } from "../types/evaluation";
 14→import {
 15→	getImpactBadgeClass,
 16→	getImpactLabel,
 17→	getIssueSeverity,
 18→	getIssueType,
 19→	getSeverityColor,
 20→	getSeverityLevel,
 21→} from "../types/evaluation";
 22→import type {
 23→	IRemediationProgressState,
 24→	RemediationHistoryItem,
 25→	RemediationResult,
 26→} from "../types/remediation";
 27→import {
 28→	countPackmindArtifacts,
 29→	formatArtifactCount,
 30→} from "../utils/packmind-artifacts";
 31→import { AGENT_GENERATED_FILES, agentLogoMap } from "./AgentLogos";
 32→import { RemediationHistory } from "./RemediationHistory";
 33→import { RemediationProgress } from "./RemediationProgress";
 34→import { CopyButton } from "./shared/CopyButton";
 35→import { Modal } from "./shared/Modal";
 36→import { PackmindLogo } from "./shared/PackmindLogo";
 37→import { PackmindProductTourModal } from "./shared/PackmindProductTourModal";
 38→
 39→const PROVIDER_EXECUTION_INFO: Record<
 40→	ProviderName,
 41→	{ writeCommand: string; securityNote: string }
 42→> = {
 43→	claude: {
 44→		writeCommand:
 45→			"claude -p --output-format json --no-session-persistence --disable-slash-commands --dangerously-skip-permissions",
 46→		securityNote:
 47→			"--dangerously-skip-permissions bypasses all file-write prompts",
 48→	},
 49→	cursor: {
 50→		writeCommand: "agent -p --output-format json --trust --force",
 51→		securityNote: "--force allows writes without confirmation",
 52→	},
 53→	codex: {
 54→		writeCommand:
 55→			"codex exec --json --full-auto --sandbox workspace-write --skip-git-repo-check",
 56→		securityNote:
 57→			"--full-auto autonomous execution, writes restricted to workspace",
 58→	},
 59→	opencode: {
 60→		writeCommand:
 61→			"opencode run --format json --model openai/gpt-5.3-codex --variant medium",
 62→		securityNote: "No sandbox restrictions documented",
 63→	},
 64→	"github-copilot": {
 65→		writeCommand:
 66→			"copilot -p <prompt> -s --no-ask-user --no-custom-instructions --allow-all-tools",
 67→		securityNote: "--allow-all-tools + --no-ask-user = fully autonomous",
 68→	},
 69→	random: {
 70→		writeCommand: "(depends on selected provider)",
 71→		securityNote: "Depends on selected provider",
 72→	},
 73→};
 74→
 75→type Phase = "idle" | "progress";
 76→
 77→interface RemediateTabProps {
 78→	evaluationId: string | null;
 79→	evaluationData: EvaluationOutput | null;
 80→	selectedIssueKeys: Set<string>;
 81→	issueKeyMap: Map<string, Issue>;
 82→	onRemoveIssue: (key: string) => void;
 83→	onClearAll: () => void;
 84→	cloudMode?: boolean;
 85→	repositoryUrl?: string | null;
 86→}
 87→
 88→export function RemediateTab({
 89→	evaluationId,
 90→	evaluationData,
 91→	selectedIssueKeys,
 92→	issueKeyMap,
 93→	onRemoveIssue,
 94→	onClearAll,
 95→	cloudMode = false,
 96→	repositoryUrl,
 97→}: RemediateTabProps) {
 98→	const api = useEvaluationApi();
 99→	const providerDetection = useProviderDetection();
100→
101→	const [showTourModal, setShowTourModal] = useState(false);
102→
103→	// Phase: idle (config visible) or progress (SSE running)
104→	const [phase, setPhase] = useState<Phase>("idle");
105→	const [targetAgent, setTargetAgent] = useState<TargetAgent>("agents-md");
106→	const [selectedProvider, setSelectedProvider] =
107→		useState<ProviderName>("claude");
108→	const [isExecuting, setIsExecuting] = useState(false);
109→	const [showConfirmModal, setShowConfirmModal] = useState(false);
110→	const [executeError, setExecuteError] = useState<string | null>(null);
111→
112→	// History state
113→	const [remediations, setRemediations] = useState<RemediationHistoryItem[]>(
114→		[],
115→	);
116→
117→	// SSE state
118→	const [sseUrl, setSseUrl] = useState<string | null>(null);
119→	const [, setActiveRemediationId] = useState<string | null>(null);
120→	const activeRemediationIdRef = useRef<string | null>(null);
121→	const [autoExpandRemediationId, setAutoExpandRemediationId] = useState<
122→		string | null
123→	>(null);
124→	const [progressState, setProgressState] = useState<IRemediationProgressState>(
125→		{
126→			status: "queued",
127→			logs: [],
128→		},
129→	);
130→
131→	// Legacy prompt generation state
132→	const [prompts, setPrompts] = useState<RemediationPromptsResponse | null>(
133→		null,
134→	);
135→
136→	// Detect providers on mount
137→	useEffect(() => {
138→		if (providerDetection.status === "idle") {
139→			providerDetection.detectProviders();
140→		}
141→	}, [providerDetection]);
142→
143→	// Load remediation history on mount / evaluationId change
144→	const refreshHistory = useCallback(async () => {
145→		if (!evaluationId) return;
146→		const data = await api.getRemediationsForEvaluation(evaluationId);
147→		setRemediations(data.remediations);
148→		return data;
149→	}, [evaluationId, api]);
150→
151→	useEffect(() => {
152→		if (!evaluationId) return;
153→
154→		let cancelled = false;
155→
156→		async function loadRemediations() {
157→			const data = await api.getRemediationsForEvaluation(evaluationId!);
158→			if (cancelled) return;
159→
160→			setRemediations(data.remediations);
161→
162→			// If there's an active job, connect SSE
163→			if (data.activeJob) {
164→				activeRemediationIdRef.current = data.activeJob.id;
165→				setActiveRemediationId(data.activeJob.id);
166→				setSseUrl(
167→					`${window.location.origin}/api/remediation/${data.activeJob.id}/progress`,
168→				);
169→				setProgressState({
170→					status: data.activeJob.status as "queued" | "running",
171→					logs: [],
172→				});
173→				setPhase("progress");
174→			}
175→		}
176→
177→		loadRemediations();
178→
179→		return () => {
180→			cancelled = true;
181→		};
182→	}, [evaluationId, api]);
183→
184→	// Available providers for the selector
185→	const availableProviders = useMemo(() => {
186→		const providers: ProviderStatus[] = [];
187→		for (const p of providerDetection.providers.values()) {
188→			if (p.available && p.name !== "random") {
189→				providers.push(p);
190→			}
191→		}
192→		return providers;
193→	}, [providerDetection.providers]);
194→
195→	// Aggregate Packmind artifact totals across all remediations
196→	const packmindTotals = useMemo(() => {
197→		let standards = 0;
198→		let skills = 0;
199→		for (const r of remediations) {
200→			const allActions = [
201→				...(r.summary?.errorFixActions ?? []),
202→				...(r.summary?.suggestionEnrichActions ?? []),
203→			];
204→			const counts = countPackmindArtifacts(allActions);
205→			standards += counts.standards;
206→			skills += counts.skills;
207→		}
208→		return { standards, skills };
209→	}, [remediations]);
210→
211→	// Resolve selected issue keys to actual issues, split by type
212→	const { errorEntries, suggestionEntries } = useMemo(() => {
213→		const errors: { key: string; issue: Issue }[] = [];
214→		const suggestions: { key: string; issue: Issue }[] = [];
215→
216→		for (const key of selectedIssueKeys) {
217→			const issue = issueKeyMap.get(key);
218→			if (!issue) continue;
219→			const type = getIssueType(issue);
220→			if (type === "error") {
221→				errors.push({ key, issue });
222→			} else {
223→				suggestions.push({ key, issue });
224→			}
225→		}
226→
227→		errors.sort(
228→			(a, b) => getIssueSeverity(b.issue) - getIssueSeverity(a.issue),
229→		);
230→		const impactOrder: Record<string, number> = {
231→			High: 0,
232→			Medium: 1,
233→			Low: 2,
234→		};
235→		suggestions.sort(
236→			(a, b) =>
237→				(impactOrder[a.issue.impactLevel ?? "Low"] ?? 2) -
238→				(impactOrder[b.issue.impactLevel ?? "Low"] ?? 2),
239→		);
240→
241→		return { errorEntries: errors, suggestionEntries: suggestions };
242→	}, [selectedIssueKeys, issueKeyMap]);
243→
244→	const totalSelected = errorEntries.length + suggestionEntries.length;
245→
246→	// SSE message handler
247→	const handleSSEMessage = useCallback(
248→		// biome-ignore lint/suspicious/noExplicitAny: SSE event data varies by type
249→		(event: any) => {
250→			const timestamp = new Date().toISOString();
251→
252→			switch (event.type) {
253→				case "remediation.started":
254→					setProgressState((prev) => ({
255→						...prev,
256→						status: "running",
257→						logs: [...prev.logs, { timestamp, message: "Remediation started" }],
258→					}));
259→					break;
260→
261→				case "remediation.progress": {
262→					const d = event.data ?? {};
263→					setProgressState((prev) => ({
264→						...prev,
265→						...(d.errorCount !== undefined && {
266→							errorCount: d.errorCount as number,
267→						}),
268→						...(d.suggestionCount !== undefined && {
269→							suggestionCount: d.suggestionCount as number,
270→						}),
271→						...(d.totalBatches !== undefined && {
272→							totalBatches: d.totalBatches as number,
273→						}),
274→						...(d.completedBatches !== undefined && {
275→							completedBatches: d.completedBatches as number,
276→						}),
277→						...(d.phase !== undefined && {
278→							currentPhase: d.phase as "errors" | "suggestions",
279→						}),
280→						...(d.runningTotalCostUsd !== undefined && {
281→							runningTotalCostUsd: d.runningTotalCostUsd as number,
282→						}),
283→						...(d.runningTotalDurationMs !== undefined && {
284→							runningTotalDurationMs: d.runningTotalDurationMs as number,
285→						}),
286→						...(d.runningTotalInputTokens !== undefined && {
287→							runningTotalInputTokens: d.runningTotalInputTokens as number,
288→						}),
289→						...(d.runningTotalOutputTokens !== undefined && {
290→							runningTotalOutputTokens: d.runningTotalOutputTokens as number,
291→						}),
292→					}));
293→					break;
294→				}
295→
296→				case "remediation.step.started": {
297→					const bi = event.data?.batchInfo as
298→						| { batchNumber: number; totalBatches: number }
299→						| undefined;
300→					const batchLabel = bi
301→						? ` (batch ${bi.batchNumber}/${bi.totalBatches})`
302→						: "";
303→					const issueSummaries = event.data?.issuesSummary as
304→						| string[]
305→						| undefined;
306→					setProgressState((prev) => ({
307→						...prev,
308→						currentStep: event.data?.step,
309→						batchInfo: bi,
310→						...(issueSummaries && {
311→							currentBatchIssues: issueSummaries,
312→						}),
313→						logs: [
314→							...prev.logs,
315→							{
316→								timestamp,
317→								message: `Step started: ${event.data?.step}${batchLabel}`,
318→							},
319→						],
320→					}));
321→					break;
322→				}
323→
324→				case "remediation.step.completed": {
325→					const bi2 = event.data?.batchInfo as
326→						| { batchNumber: number; totalBatches: number }
327→						| undefined;
328→					const batchLabel2 = bi2
329→						? ` (batch ${bi2.batchNumber}/${bi2.totalBatches})`
330→						: "";
331→					const step = event.data?.step as string | undefined;
332→					const batchDurationMs = event.data?.batchDurationMs as
333→						| number
334→						| undefined;
335→					const batchCostUsd = event.data?.batchCostUsd as number | undefined;
336→					const batchInputTokens = event.data?.batchInputTokens as
337→						| number
338→						| undefined;
339→					const batchOutputTokens = event.data?.batchOutputTokens as
340→						| number
341→						| undefined;
342→
343→					const hasBatchStats =
344→						batchDurationMs !== undefined && batchCostUsd !== undefined;
345→					let logMessage = `Step completed: ${step}${batchLabel2}`;
346→					if (hasBatchStats) {
347→						const phaseName =
348→							step === "executing_error_fix"
349→								? "Error fix"
350→								: "Suggestion enrich";
351→						const label = bi2
352→							? `${phaseName} batch ${bi2.batchNumber}/${bi2.totalBatches}`
353→							: phaseName;
354→						logMessage = `${label} completed: ${Math.round(batchDurationMs / 1000)}s, $${batchCostUsd.toFixed(4)}`;
355→					}
356→
357→					setProgressState((prev) => ({
358→						...prev,
359→						batchInfo: undefined,
360→						currentBatchIssues: undefined,
361→						...(hasBatchStats && {
362→							lastBatchStats: {
363→								durationMs: batchDurationMs!,
364→								costUsd: batchCostUsd!,
365→								inputTokens: batchInputTokens ?? 0,
366→								outputTokens: batchOutputTokens ?? 0,
367→							},
368→						}),
369→						logs: [...prev.logs, { timestamp, message: logMessage }],
370→					}));
371→					break;
372→				}
373→
374→				case "remediation.completed": {
375→					setProgressState((prev) => ({
376→						...prev,
377→						status: "completed",
378→						result: event.data?.result as RemediationResult | undefined,
379→						logs: [
380→							...prev.logs,
381→							{ timestamp, message: "Remediation completed" },
382→						],
383→					}));
384→					// Reset to idle, refresh history, clear selection
385→					// Capture completed remediation ID for auto-expand
386→					if (activeRemediationIdRef.current) {
387→						setAutoExpandRemediationId(activeRemediationIdRef.current);
388→					}
389→					activeRemediationIdRef.current = null;
390→					setActiveRemediationId(null);
391→					setSseUrl(null);
392→					setPhase("idle");
393→					onClearAll();
394→					refreshHistory();
395→					break;
396→				}
397→
398→				case "remediation.failed":
399→					setProgressState((prev) => ({
400→						...prev,
401→						status: "failed",
402→						error: event.data?.error,
403→						logs: [
404→							...prev.logs,
405→							{
406→								timestamp,
407→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
408→							},
409→						],
410→					}));
411→					setExecuteError(event.data?.error?.message || "Remediation failed");
412→					setSseUrl(null);
413→					activeRemediationIdRef.current = null;
414→					setActiveRemediationId(null);
415→					setPhase("idle");
416→					refreshHistory();
417→					break;
418→			}
419→		},
420→		[onClearAll, refreshHistory],
421→	);
422→
423→	useSSE({
424→		url: sseUrl,
425→		onMessage: handleSSEMessage,
426→	});
427→
428→	// Execute remediation
429→	const handleExecute = useCallback(async () => {
430→		if (!evaluationId || totalSelected === 0) return;
431→
432→		setIsExecuting(true);
433→		setExecuteError(null);
434→		setPrompts(null);
435→
436→		try {
437→			const issues = [
438→				...errorEntries.map((e) => e.issue),
439→				...suggestionEntries.map((e) => e.issue),
440→			];
441→
442→			const response = await api.executeRemediation(
443→				evaluationId,
444→				issues,
445→				targetAgent,
446→				selectedProvider,
447→			);
448→
449→			activeRemediationIdRef.current = response.remediationId;
450→			setActiveRemediationId(response.remediationId);
451→			setSseUrl(response.sseUrl);
452→			setProgressState({ status: "queued", logs: [] });
453→			setPhase("progress");
454→		} catch (err) {
455→			const message =
456→				err instanceof Error ? err.message : "Failed to start remediation";
457→			setExecuteError(message);
458→		} finally {
459→			setIsExecuting(false);
460→		}
461→	}, [
462→		evaluationId,
463→		totalSelected,
464→		errorEntries,
465→		suggestionEntries,
466→		targetAgent,
467→		selectedProvider,
468→		api,
469→	]);
470→
471→	// Generate prompts (legacy copy-paste mode)
472→	// Delete a remediation from history
473→	const handleDeleteRemediation = useCallback(
474→		async (remediationId: string) => {
475→			await api.deleteRemediation(remediationId);
476→			setRemediations((prev) => prev.filter((r) => r.id !== remediationId));
477→		},
478→		[api],
479→	);
480→
481→	if (!evaluationData) {
482→		return (
483→			<div className="card text-center py-12">
484→				<p className="text-body-muted">
485→					No evaluation data. Run an evaluation first to generate remediation
486→					prompts.
487→				</p>
488→			</div>
489→		);
490→	}
491→
492→	// ─── PROGRESS PHASE ────────────────────────────────────────────────
493→	if (phase === "progress") {
494→		return (
495→			<div className="space-y-6">
496→				<div className="card">
497→					<h2 className="text-heading text-slate-100">Executing Remediation</h2>
498→					<p className="text-body-muted mt-1">
499→						Running {selectedProvider} agent to fix{" "}
500→						{totalSelected > 0 ? totalSelected : "selected"} issue
501→						{totalSelected !== 1 ? "s" : ""}...
502→					</p>
503→				</div>
504→				<RemediationProgress
505→					currentStep={progressState.currentStep}
506→					batchInfo={progressState.batchInfo}
507→					logs={progressState.logs}
508→					errorCount={progressState.errorCount}
509→					suggestionCount={progressState.suggestionCount}
510→					totalBatches={progressState.totalBatches}
511→					completedBatches={progressState.completedBatches}
512→					currentPhase={progressState.currentPhase}
513→					runningTotalCostUsd={progressState.runningTotalCostUsd}
514→					runningTotalDurationMs={progressState.runningTotalDurationMs}
515→					runningTotalInputTokens={progressState.runningTotalInputTokens}
516→					runningTotalOutputTokens={progressState.runningTotalOutputTokens}
517→					currentBatchIssues={progressState.currentBatchIssues}
518→				/>
519→			</div>
520→		);
521→	}
522→
523→	// ─── IDLE PHASE (config + history) ─────────────────────────────────
524→	return (
525→		<div className="space-y-6">
526→			<div className="card">
527→				<h2 className="text-heading text-slate-100">Remediation</h2>
528→				<p className="text-body-muted mt-1">
529→					Execute remediation to fix issues automatically, or generate
530→					copy-paste prompts
531→				</p>
532→			</div>
533→
534→			{/* Past Remediations History */}
535→			<RemediationHistory
536→				remediations={remediations}
537→				onDelete={handleDeleteRemediation}
538→				onRefresh={refreshHistory}
539→				cloudMode={cloudMode}
540→				autoExpandId={autoExpandRemediationId}
541→				onAutoExpandHandled={() => setAutoExpandRemediationId(null)}
542→				parentScore={evaluationData?.metadata?.contextScore?.score}
543→				parentGrade={evaluationData?.metadata?.contextScore?.grade}
544→				defaultOpen={selectedIssueKeys.size === 0}
545→				hasRepoUrl={
546→					!!repositoryUrl &&
547→					repositoryUrl !== "unknown" &&
548→					(repositoryUrl.startsWith("http") || repositoryUrl.startsWith("git@"))
549→				}
550→			/>
551→
552→			{/* Packmind persistent promotion section */}
553→			<div className="card border-2 packmind-section">
554→				<div className="flex items-start gap-4">
555→					<PackmindLogo className="h-8 flex-shrink-0 mt-0.5" />
556→					<div className="flex-1 min-w-0">
557→						<h3 className="text-subheading text-slate-100 mb-1">
558→							What's next with your playbook?
559→						</h3>
560→						{packmindTotals.standards + packmindTotals.skills > 0 && (
561→							<p className="text-base text-slate-300 mb-1">
562→								Your remediations have created{" "}
563→								<span className="font-bold text-blue-400 bg-blue-500/15 px-1.5 py-0.5 rounded">
564→									{formatArtifactCount(
565→										packmindTotals.standards,
566→										packmindTotals.skills,
567→									)}
568→								</span>{" "}
569→								so far.
570→							</p>
571→						)}
572→						<p className="text-body text-slate-400">
573→							Your team's AI agent playbook is taking shape. Packmind helps you
574→							centralize coding standards and skills, distribute them across
575→							repos, and add governance workflows.
576→						</p>
577→						<div className="flex gap-3 mt-3">
578→							<a
579→								href="https://packmind.com"
580→								target="_blank"
581→								rel="noopener noreferrer"
582→								className="btn-secondary"
583→							>
584→								Explore Packmind
585→							</a>
586→							<button
587→								onClick={() => setShowTourModal(true)}
588→								className="btn-secondary"
589→							>
590→								Get product tour
591→							</button>
592→						</div>
593→					</div>
594→				</div>
595→				<PackmindProductTourModal
596→					isOpen={showTourModal}
597→					onClose={() => setShowTourModal(false)}
598→				/>
599→			</div>
600→
601→			{/* Empty state when no issues selected */}
602→			{totalSelected === 0 ? (
603→				<div className="card text-center py-12">
604→					<svg
605→						className="w-12 h-12 text-slate-600 mx-auto mb-4"
606→						fill="none"
607→						stroke="currentColor"
608→						viewBox="0 0 24 24"
609→					>
610→						<path
611→							strokeLinecap="round"
612→							strokeLinejoin="round"
613→							strokeWidth={1.5}
614→							d="M12 4v16m8-8H4"
615→						/>
616→					</svg>
617→					<p className="text-body-muted">
618→						No issues selected. Use the{" "}
619→						<span className="inline-flex items-center justify-center w-5 h-5 rounded bg-slate-700 text-slate-300 text-xs align-middle mx-0.5">
620→							+
621→						</span>{" "}
622→						button on issue cards in the Errors and Suggestions tabs.
623→					</p>
624→				</div>
625→			) : (
626→				<div className="card space-y-5">
627→					{/* Target Agent */}
628→					<div>
629→						<label className="text-label text-slate-300 block mb-2">
630→							Target for markdown file rendering
631→						</label>
632→						<div className="flex gap-2">
